#include <cmath>

extern "C" double mms_source_dens(double x, double y, double t) {
    return (-0.20000000000000001*x*(0.5*sin(x)*cos(1.0*t)*cos(y) + 2.0)*sin(x)*sin(y)*cos(1.0*t) - 0.5*x*sin(1.0*t)*sin(x)*cos(y) + 0.10000000000000001*x*sin(y)*pow(cos(1.0*t), 2)*pow(cos(x), 2)*cos(y) - 0.5*(0.29999999999999999*sin(x)*sin(y)*cos(1.0*t) + 1.0)*sin(x)*sin(y)*cos(1.0*t) + 0.29999999999999999*(0.5*sin(x)*cos(1.0*t)*cos(y) + 2.0)*sin(x)*cos(1.0*t)*cos(y) + 0.20000000000000001*(0.5*sin(x)*cos(1.0*t)*cos(y) + 2.0)*sin(y)*cos(1.0*t)*cos(x))/x;
}

extern "C" double mms_source_mom1(double x, double y, double t) {
    return (-x*(0.20000000000000001*sin(x)*cos(1.0*t)*cos(y) + 0.40000000000000002)*sin(1.0*t)*sin(y)*cos(x) - x*(0.080000000000000016*(0.5*sin(x)*cos(1.0*t)*cos(y) + 2.0)*sin(x)*pow(sin(y), 2)*cos(1.0*t)*cos(x) + 0.40000000000000002*sin(x)*cos(y) - 0.020000000000000004*pow(sin(y), 2)*pow(cos(1.0*t), 2)*pow(cos(x), 3)*cos(y))*cos(1.0*t) - pow(0.29999999999999999*sin(x)*sin(y)*cos(1.0*t) + 1.0, 2)*(0.5*sin(x)*cos(1.0*t)*cos(y) + 2.0) + 0.20000000000000001*(0.29999999999999999*sin(x)*sin(y)*cos(1.0*t) + 1.0)*(0.5*sin(x)*cos(1.0*t)*cos(y) + 2.0)*cos(1.0*t)*cos(x)*cos(y) - 0.10000000000000001*(0.29999999999999999*sin(x)*sin(y)*cos(1.0*t) + 1.0)*sin(x)*pow(sin(y), 2)*pow(cos(1.0*t), 2)*cos(x) + (0.020000000000000004*sin(x)*cos(1.0*t)*cos(y) + 0.080000000000000016)*pow(sin(y), 2)*pow(cos(1.0*t), 2)*pow(cos(x), 2) + 0.059999999999999998*(0.5*sin(x)*cos(1.0*t)*cos(y) + 2.0)*sin(x)*sin(y)*pow(cos(1.0*t), 2)*cos(x)*cos(y))/x;
}

extern "C" double mms_source_mom2(double x, double y, double t) {
    return (-x*(0.29999999999999999*sin(x)*sin(y)*cos(1.0*t)*cos(y) + 0.59999999999999998*sin(y) + 0.5*cos(y))*sin(1.0*t)*sin(x) + (-0.5*pow(0.29999999999999999*sin(x)*sin(y)*cos(1.0*t) + 1.0, 2)*sin(x)*sin(y) + 0.59999999999999998*(0.29999999999999999*sin(x)*sin(y)*cos(1.0*t) + 1.0)*(0.5*sin(x)*cos(1.0*t)*cos(y) + 2.0)*sin(x)*cos(y) - 0.40000000000000002*sin(y)*cos(x))*cos(1.0*t) + (-0.20000000000000001*x*(0.29999999999999999*sin(x)*sin(y)*cos(1.0*t) + 1.0)*(0.5*sin(x)*cos(1.0*t)*cos(y) + 2.0)*sin(x) + 0.10000000000000001*x*(0.29999999999999999*sin(x)*sin(y)*cos(1.0*t) + 1.0)*cos(1.0*t)*pow(cos(x), 2)*cos(y) + x*(0.029999999999999999*sin(x)*cos(1.0*t)*cos(y) + 0.12)*sin(y)*cos(1.0*t)*pow(cos(x), 2) + 0.40000000000000002*(0.29999999999999999*sin(x)*sin(y)*cos(1.0*t) + 1.0)*(0.5*sin(x)*cos(1.0*t)*cos(y) + 2.0)*cos(x))*sin(y)*cos(1.0*t))/x;
}

extern "C" double mms_source_etot(double x, double y, double t) {
    return (1.0/2.0)*(-0.20000000000000001*x*((0.5*sin(x)*cos(1.0*t)*cos(y) + 2.0)*(pow(0.29999999999999999*sin(x)*sin(y)*cos(1.0*t) + 1.0, 2) + 0.040000000000000008*pow(sin(y), 2)*pow(cos(1.0*t), 2)*pow(cos(x), 2)) + 2.0*cos(1.0*t)*cos(x)*cos(y) + 14.999999999999998)*sin(x)*sin(y)*cos(1.0*t) - x*((0.5*sin(x)*cos(1.0*t)*cos(y) + 2.0)*(0.099999999999999992*pow(sin(x), 2)*sin(y)*cos(1.0*t) + 0.59999999999999998*sin(x) + 0.080000000000000002*sin(y)*cos(1.0*t))*sin(y) + 0.5*(pow(0.29999999999999999*sin(x)*sin(y)*cos(1.0*t) + 1.0, 2) + 0.040000000000000008*pow(sin(y), 2)*pow(cos(1.0*t), 2)*pow(cos(x), 2))*sin(x)*cos(y) + 1.2*cos(x)*cos(y))*sin(1.0*t) + 0.20000000000000001*x*((0.099999999999999978*sin(x)*sin(y)*cos(1.0*t) + 0.59999999999999998)*(0.5*sin(x)*cos(1.0*t)*cos(y) + 2.0)*sin(y)*cos(x) + 0.5*(pow(0.29999999999999999*sin(x)*sin(y)*cos(1.0*t) + 1.0, 2) + 0.040000000000000008*pow(sin(y), 2)*pow(cos(1.0*t), 2)*pow(cos(x), 2))*cos(x)*cos(y) - 2.0*sin(x)*cos(y))*sin(y)*pow(cos(1.0*t), 2)*cos(x) - (0.29999999999999999*sin(x)*sin(y)*cos(1.0*t) + 1.0)*(-(0.5*sin(x)*cos(1.0*t)*cos(y) + 2.0)*(0.099999999999999992*pow(sin(x), 2)*sin(y)*cos(1.0*t) + 0.59999999999999998*sin(x) + 0.080000000000000002*sin(y)*cos(1.0*t))*cos(y) + 0.5*(pow(0.29999999999999999*sin(x)*sin(y)*cos(1.0*t) + 1.0, 2) + 0.040000000000000008*pow(sin(y), 2)*pow(cos(1.0*t), 2)*pow(cos(x), 2))*sin(x)*sin(y) + 2.0*sin(y)*cos(x))*cos(1.0*t) + 0.29999999999999999*((0.5*sin(x)*cos(1.0*t)*cos(y) + 2.0)*(pow(0.29999999999999999*sin(x)*sin(y)*cos(1.0*t) + 1.0, 2) + 0.040000000000000008*pow(sin(y), 2)*pow(cos(1.0*t), 2)*pow(cos(x), 2)) + 2.0*cos(1.0*t)*cos(x)*cos(y) + 14.999999999999998)*sin(x)*cos(1.0*t)*cos(y) + 0.20000000000000001*((0.5*sin(x)*cos(1.0*t)*cos(y) + 2.0)*(pow(0.29999999999999999*sin(x)*sin(y)*cos(1.0*t) + 1.0, 2) + 0.040000000000000008*pow(sin(y), 2)*pow(cos(1.0*t), 2)*pow(cos(x), 2)) + 2.0*cos(1.0*t)*cos(x)*cos(y) + 14.999999999999998)*sin(y)*cos(1.0*t)*cos(x))/x;
}
